<template><van-popup v-model:show="visible" position="bottom" round class="person-popup"><header><h2>{{title}}（{{members.length}}）</h2><button type="button" @click="visible=false"><van-icon name="cross"/></button></header><div class="list"><div v-for="member in members" :key="member.id" class="row"><span class="avatar">{{(member.name||'?').slice(0,1)}}</span><strong>{{member.name}}</strong><img v-if="deletable" :src="deleteIcon" alt="删除"/></div></div></van-popup></template>
<script setup>import{computed}from'vue';import deleteIcon from'../../assets/figma-vehicle-delete.svg';const props=defineProps({show:Boolean,title:{type:String,default:'出园人'},members:{type:Array,default:()=>[]},deletable:Boolean});const emit=defineEmits(['update:show','remove']);const visible=computed({get:()=>props.show,set:v=>emit('update:show',v)})</script>
<style scoped>.person-popup{max-height:80vh;overflow:hidden;background:#F2F3F5}.person-popup header{position:relative;height:64px;display:flex;align-items:center;justify-content:center}.person-popup header h2{margin:0;color:#1D2129;font:600 18px/24px "PingFang SC",sans-serif}.person-popup header button{position:absolute;top:14px;right:16px;width:36px;height:36px;border:0;border-radius:50%;color:#86909C;background:#fff;font-size:18px}.list{max-height:calc(80vh - 64px);margin:0 16px 16px;padding:8px 16px;overflow-y:auto;border-radius:12px;background:#fff}.row{min-height:56px;padding:8px 0;box-sizing:border-box;display:flex;align-items:center;gap:12px;border-bottom:1px solid #F2F3F5}.row:last-child{border-bottom:0}.avatar{width:24px;height:24px;display:flex;align-items:center;justify-content:center;border-radius:50%;color:#fff;background:#C9CDD4;font:600 12px/24px "PingFang SC",sans-serif}.row strong{flex:1;color:#1D2129;font:500 16px/24px "PingFang SC",sans-serif}.row img{width:18px;height:18px}</style>
